```cpp
#include <sourcemod>
#include <csgorank>

#pragma semicolon 1

public Plugin:myinfo =
{
    name = "Rank Changer",
    author = "Your Name",
    description = "Allows users to change their displayed matchmaking rank",
    version = "1.0",
    url = "https://example.com"
};

public OnPluginStart()
{
    RegConsoleCmd("sm_rank", Command_Rank);
}

public Action:Command_Rank(client, args)
{
    if (args < 1)
    {
        CPrintToChat(client, "%s Usage: sm_rank <rank>", "Rank Changer");
        return Plugin_Handled;
    }

    char rank[64];
    GetCmdArg(1, rank, sizeof(rank));

    if (StrEqual(rank, "unranked"))
    {
        CUserStats(client).SetRank(0);
    }
    else
    {
        int rankIndex = CSGORank_GetRankIndex(rank);
        if (rankIndex != -1)
        {
            CUserStats(client).SetRank(rankIndex);
        }
        else
        {
            CPrintToChat(client, "%s Invalid rank: %s", "Rank Changer", rank);
        }
    }

    return Plugin_Handled;
}
```

This plugin uses the `CUserStats` class to get the user's current rank and then allows the user to change it to any rank they want. The `CSGORank_GetRankIndex` function is used to get the index of the rank from the rank string.

